package kr.chagok.ledger;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import java.io.*;import java.time.*;import java.util.*;
final class PlanSelectorChecks {
 static void open(DeviceChecks t,MainActivity a,PlanningData.Repeat old)throws Exception{t.runOnMainSync(()->{try{DeviceChecks.invoke(a,"repeatEditor",new Class[]{PlanningData.Repeat.class},old);}catch(Exception e){throw new RuntimeException(e);}});t.waitForIdleSync();}
 static void pick(DeviceChecks t,String field,String value)throws Exception{t.runOnMainSync(()->t.windowDesc(field+" 선택").performClick());t.waitForIdleSync();item(t,value);t.waitForIdleSync();}
 static void item(DeviceChecks t,String value)throws Exception{ListView list=(ListView)t.windowView(ListView.class);int found=-1;for(int i=0;i<list.getAdapter().getCount();i++)if(value.equals(list.getAdapter().getItem(i).toString())){found=i;break;}t.eq(true,found>=0);final int index=found;final boolean[] clicked={false};t.runOnMainSync(()->clicked[0]=list.performItemClick(list.getChildAt(index-list.getFirstVisiblePosition()),index,list.getAdapter().getItemId(index)));t.eq(true,clicked[0]);t.waitForIdleSync();}
 static String category(DeviceChecks t)throws Exception{return ((EditText)t.windowDesc("반복 상세 분류")).getText().toString();}
 static void run(DeviceChecks t)throws Exception{
  Context ctx=t.getTargetContext();try(LedgerDb db=CategoryChecks.fresh(ctx)){}final MainActivity a=StartupChecks.start(t,false);CategoryStore names=new CategoryStore(ctx);String[] cats={"내 월급","내 식비","내 적금","내 미국투자","내 적금"};for(int i=0;i<4;i++)names.remember(Ledger.INPUT_TYPES[i],cats[i]);
  try(LedgerDb db=new LedgerDb(ctx)){
   for(int i=0;i<5;i++){open(t,a,null);t.planSpinner("반복 돈의 성격",i);t.planField("반복 이름","선택검사"+i);t.planField("반복 금액 (원)","100");t.eq(null,((EditText)t.windowDesc("반복 상세 분류")).getKeyListener());t.eq(false,t.windowDesc("반복 상세 분류").isFocusable());t.runOnMainSync(()->t.windowDesc("반복 상세 분류 선택").performClick());t.waitForIdleSync();t.eq(true,t.activeText(cats[i]));
    for(int k=0;k<4;k++)if(!cats[k].equals(cats[i]))t.eq(false,t.activeText(cats[k]));item(t,cats[i]);t.waitForIdleSync();t.eq(cats[i],category(t));if(i==1)t.screenshot(ctx,"repeat-selected-"+a.getResources().getConfiguration().fontScale);t.clickText("저장");t.waitForIdleSync();t.eq(i+1,db.planning().repeats.size());t.eq(0,db.all().size());t.eq(cats[i],db.planning().repeats.get(i).category);}
   open(t,a,db.planning().repeats.get(1));t.eq("내 식비",category(t));t.planSpinner("반복 돈의 성격",2);t.eq("",category(t));t.clickText("저장");t.waitForIdleSync();t.eq(true,t.activeText("상세 분류를 선택해 주세요."));pick(t,"반복 상세 분류","내 적금");t.planSpinner("반복 돈의 성격",4);t.eq("내 적금",category(t));t.clickText("취소");t.waitForIdleSync();t.eq("지출",db.planning().repeats.get(1).type);
   PlanningData.Repeat existing=db.planning().repeats.get(3);names.delete("투자",existing.category);open(t,a,existing);t.eq(existing.category,category(t));t.clickText("저장");t.waitForIdleSync();t.eq(existing.id,db.planning().repeats.get(4).id); // put replaces at end, identity preserved.
   open(t,a,null);t.planSpinner("반복 돈의 성격",3);t.runOnMainSync(()->t.windowDesc("반복 상세 분류 선택").performClick());t.waitForIdleSync();t.eq(false,t.activeText("내 미국투자"));t.clickText("새 상세 분류 추가");t.waitForIdleSync();t.planField("상세 분류 이름","\u00a0새 투자\u3000");t.clickText("추가");t.waitForIdleSync();t.eq("새 투자",category(t));t.clickText("취소");t.waitForIdleSync();
   // Fixed-type goal picker excludes other groups and can return to whole-group scope.
   for(String type:new String[]{"지출","저축","투자"}){t.runOnMainSync(()->{try{DeviceChecks.invoke(a,"limitEditor",new Class[]{PlanningData.Limit.class,String.class},null,type);}catch(Exception e){throw new RuntimeException(e);}});t.waitForIdleSync();String field="상세 분류 (비우면 전체)";pick(t,field,type.equals("지출")?"내 식비":type.equals("저축")?"내 적금":"새 투자");t.runOnMainSync(()->t.windowDesc(field+" 전체 적용").performClick());t.waitForIdleSync();t.eq("",((EditText)t.windowDesc(field)).getText().toString());t.clickText("취소");t.waitForIdleSync();}
   PlanningData p=db.planning();p.put(new PlanningData.Limit("*","지출","",1000));p.put(new PlanningData.Limit("2026-11","저축","내 적금",500));p.put(new PlanningData.Limit("*","투자","새 투자",100));p.put(new PlanningData.Favorite("my-fav","새 틀","투자",100,"새 투자","메모"));p.selectLivingCategories(Arrays.asList("내 식비"));db.savePlanning(p);db.save(new Ledger.Entry("original-xlsx",LocalDate.now().toString(),"수입",2000,"내 월급","원본",0),false);
   File full=new File(ctx.getExternalFilesDir(null),"plans-full.xlsx");t.runOnMainSync(()->a.onActivityResult(10,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(full))));t.awaitIdle(a);XlsxIO.ReadResult read;try(InputStream in=new FileInputStream(full)){read=XlsxIO.read(in);}t.eq(p.encode(),read.planning.encode());t.eq(1,read.entries.size());t.eq(0,read.invalidRows);
   File monthly=new File(ctx.getExternalFilesDir(null),"plans-monthly.xlsx");t.runOnMainSync(()->a.onActivityResult(13,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(monthly))));t.awaitIdle(a);try(InputStream in=new FileInputStream(monthly)){t.eq(null,XlsxIO.read(in).planning);}
   String expected=p.encode();StartupChecks.close(t,a);db.close();try(LedgerDb clean=CategoryChecks.fresh(ctx)){}final MainActivity restored=StartupChecks.start(t,false);
   t.runOnMainSync(()->restored.onActivityResult(12,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(full))));t.awaitIdle(restored);t.eq(true,t.activeText("계획 포함 백업 가져오기"));t.clickText("취소");t.waitForIdleSync();try(LedgerDb clean=new LedgerDb(ctx)){t.eq(0,clean.all().size());t.eq(0,clean.planning().repeats.size());}
   t.runOnMainSync(()->restored.onActivityResult(12,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(full))));t.awaitIdle(restored);t.clickText("확인하고 추가");t.awaitIdle(restored);try(LedgerDb clean=new LedgerDb(ctx)){t.eq(expected,clean.planning().encode());t.eq(1,clean.all().size());t.eq(5,clean.planning().repeats.size());t.eq(true,new CategoryStore(ctx).choices("투자",clean.all(),clean.planning()).contains("새 투자"));t.eq(false,new CategoryStore(ctx).choices("지출",clean.all(),clean.planning()).contains("새 투자"));
    // Existing keys/IDs keep the app value; an all-plan-only workbook is still importable.
    PlanningData incoming=new PlanningData();incoming.put(new PlanningData.Limit("*","지출","",9999));incoming.put(new PlanningData.Favorite("new-fav","추가 틀","지출",50,"내 식비",""));incoming.selectLivingCategories(Collections.emptyList());File only=new File(ctx.getExternalFilesDir(null),"plans-only.xlsx");try(OutputStream o=new FileOutputStream(only)){XlsxIO.writePlanning(o,Collections.emptyList(),Collections.emptyList(),incoming);}t.runOnMainSync(()->restored.onActivityResult(12,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(only))));t.awaitIdle(restored);t.eq(true,t.activeText("계획 포함 백업 가져오기"));t.clickText("확인하고 추가");t.awaitIdle(restored);t.eq(1000L,clean.planning().limits.stream().filter(v->v.type.equals("지출")).findFirst().get().amount);t.eq(2,clean.planning().favorites.size());t.eq(new TreeSet<>(Arrays.asList("내 식비")),clean.planning().livingCategories());t.eq(1,clean.all().size());
    // Failed plan write rolls back incoming rows too.
    String before=CategoryChecks.state(clean);PlanningData more=new PlanningData();more.put(new PlanningData.Favorite("fail-fav","안 들어갈 틀","저축",10,"내 적금",""));File fail=new File(ctx.getExternalFilesDir(null),"plans-rollback.xlsx");try(OutputStream o=new FileOutputStream(fail)){XlsxIO.writePlanning(o,Arrays.asList(new Ledger.Entry("rollback-xlsx",LocalDate.now().toString(),"수입",1,"내 월급","",0)),Collections.emptyList(),more);}clean.getWritableDatabase().execSQL("CREATE TRIGGER reject_plan BEFORE INSERT ON feature_state WHEN NEW.key='planning' BEGIN SELECT RAISE(ABORT,'forced'); END");t.runOnMainSync(()->restored.onActivityResult(12,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(fail))));t.awaitIdle(restored);t.clickText("확인하고 추가");t.awaitIdle(restored);t.eq(true,t.activeText("저장하지 못했어요"));t.eq(before,CategoryChecks.state(clean));clean.getWritableDatabase().execSQL("DROP TRIGGER reject_plan");t.clickText("확인");t.waitForIdleSync();
   }
   StartupChecks.close(t,restored);
  }
 }
}
